import json
import math
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    """Return all local validation errors without making an API call."""
    errors = []
    if not isinstance(record, dict):
        return [{"code": "invalid_record", "field": None, "value": record}]

    for field_name in REQUIRED_FIELDS:
        value = record.get(field_name)
        if field_name not in record or value is None or (
            isinstance(value, str) and not value.strip()
        ):
            errors.append({
                "code": "required",
                "field": field_name,
                "value": value,
            })

    amount = record.get("amount")
    if amount is not None and (
        isinstance(amount, bool)
        or not isinstance(amount, (int, float))
        or not math.isfinite(amount)
        or amount < 0
    ):
        errors.append({
            "code": "invalid_amount",
            "field": "amount",
            "value": amount,
        })
    return errors


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A missing profile is an expected condition: system defaults are used.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    failures = []
    for index, record in enumerate(payload):
        errors = validate_record(record)
        if errors:
            failures.append({"index": index, "item": record, "errors": errors})
            continue

        enriched = enrich(record)
        try:
            normalized = normalize(enriched)
        except (KeyError, ValueError) as exc:
            failures.append({
                "index": index,
                "item": record,
                "errors": [{
                    "code": "normalization",
                    "field": "currency",
                    "value": enriched.get("currency"),
                    "message": str(exc),
                }],
            })
            continue
        results.append(send_transaction(normalized))
    return {
        "results": results,
        "failures": failures,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
        "summary": {
            "total": len(payload),
            "succeeded": len(results),
            "failed": len(failures),
        },
    }
